add(9,'The Name Shouted from the Sea','Safely offshore, Odysseus reveals his name; Polyphemus calls on Poseidon for vengeance.','cyclopes',['odysseus','polyphemus','poseidon'],[], 'The next morning',4,{},true)
add(10,'Aeolus Bags the Winds','Aeolus hosts the crew and seals the adverse winds in an ox-hide bag.','aeolia',['odysseus','aeolus','eurylochus'],['wind-bag'], 'One month',2,{},true)
add(10,'Ithaca Lost in Sight','Within sight of home, the crew opens the bag and the released storm drives them back.','ithaca-gate',['odysseus','eurylochus','aeolus'],['wind-bag'], 'Nine days sailing',4,{},true)
add(10,'Aeolus Refuses a Second Passage','Driven back to Aeolia, Odysseus asks for help again; Aeolus reads the disaster as divine rejection and expels him.','aeolia',['odysseus','aeolus','eurylochus'],[], 'The same day',3,{},true)
add(10,'The Laestrygonian Harbour','Giants attack from the cliffs and destroy every ship except Odysseus’s vessel outside the harbour.','telepylus',['odysseus','eurylochus','antiphates'],[], 'Six days later',5,{},true)
add(10,'Circe Transforms the Scouts','Circe drugs the visitors and changes them into swine; Eurylochus escapes to warn Odysseus.','aeaea',['circe','eurylochus','odysseus'],[], 'After reaching Aeaea',4,{},true)
add(10,'Moly Defeats the Spell','Hermes gives Odysseus moly; he resists Circe’s potion and compels restoration of the crew.','aeaea',['odysseus','circe','hermes','eurylochus'],['moly'], 'That day',4,{},true)
add(10,'A Year with Circe','The restored crew remains in comfort until companions remind Odysseus of home.','aeaea',['odysseus','circe','eurylochus'],[], 'One year',2,{},true)
add(11,'The Black Ship Reaches the Cimmerians','Odysseus beaches the ship at the sunless boundary of Ocean and leads the crew toward the place Circe prescribed for speaking with the dead.','cimmerian-gate',['odysseus','eurylochus'],[], 'After crossing Ocean',3,{},true)
add(11,'Elpenor Asks for Burial','The first shade to speak is the unburied Elpenor, who demands funeral rites on Aeaea.','sacrifice-pit',['odysseus','elpenor'],[], 'After crossing Ocean',3,{},true)
add(11,'Tiresias Defines the Return','Tiresias warns against the cattle of Helios and foretells a lonely homecoming and inland atonement.','sacrifice-pit',['odysseus','tiresias'],['cattle'], 'Moments later',4,{},true)
add(11,'Anticleia Embraces Only Air','Odysseus learns how his mother died and three times fails to hold her shade.','asphodel',['odysseus','anticleia'],[], 'Later in the rite',4,{},true)
add(11,'The Heroes Among the Dead','Odysseus hears Agamemnon’s warning and Achilles’s rejection of glory in death.','asphodel',['odysseus','agamemnon','achilles'],[], 'Before dawn',3,{},true)
add(12,'The Sirens’ Song','The crew’s ears are sealed with wax while the bound Odysseus struggles toward the promised knowledge.','sirens',['odysseus','eurylochus'],['wax'], 'After leaving Aeaea',4,{},true)
add(12,'Scylla Takes Six','The ship avoids Charybdis, but Scylla seizes six men from the deck.','scylla',['odysseus','eurylochus','scylla'],[], 'The same day',5,{},true)
add(12,'The Cattle Are Slaughtered','While Odysseus sleeps, Eurylochus persuades the starving crew to sacrifice Helios’s cattle.','thrinacia',['odysseus','eurylochus','helios','zeus'],['cattle'], 'One month trapped by weather',5,{},true)
add(12,'Helios Demands Justice','After learning that his sacred herd has been killed, Helios demands punishment and Zeus promises to destroy the offenders’ ship.','olympus',['helios','zeus'],['cattle'], 'Soon afterward',4,{},true)
add(12,'Zeus Destroys the Last Ship','A thunderbolt shatters the ship; Odysseus alone survives and drifts eventually to Ogygia.','thrinacia',['odysseus','zeus','poseidon'],[], 'Soon after departure',5,{},true)
add(13,'The Sleeping King Lands','The Phaeacians carry Odysseus home asleep and arrange his gifts beside the harbour.','ithaca-harbour',['odysseus','alcinous'],['gifts'], 'One night',2)
add(13,'Athena Reveals Ithaca','Athena ends Odysseus’s disorientation, hides the treasure, and disguises him as an old beggar.','athena-cave',['odysseus','athena'],['gifts'], 'That morning',2)
add(14,'Eumaeus Welcomes the Beggar','Eumaeus protects the stranger from his dogs, feeds him, and condemns the suitors.','eumaeus-hut',['odysseus','eumaeus'],[], 'Later that day',2)
add(14,'A Cretan Tale','Odysseus invents a detailed Cretan identity to test Eumaeus’s loyalty and expectations.','eumaeus-hut',['odysseus','eumaeus'],['brooch'], 'That evening',2)
add(15,'Telemachus Leaves Sparta','Prompted by Athena, Telemachus accepts gifts, departs Menelaus’s court, and sails home.','sparta',['telemachus','athena','menelaus','helen','pisistratus'],[], 'The next morning',2)
add(15,'The Ambush Is Avoided','Telemachus follows Athena’s route around the suitors waiting in the strait.','ithaca-harbour',['telemachus','athena','antinous'],[], 'One night at sea',3)
add(16,'Athena Restores Odysseus','Before Telemachus, Athena removes the beggar disguise and reveals the father he barely remembers.','eumaeus-hut',['odysseus','telemachus','athena','eumaeus'],[], 'That morning',4)
add(16,'Father and Son Plan','They count enemies, identify possible allies, and arrange the removal of weapons from the hall.','eumaeus-hut',['odysseus','telemachus'],[], 'The same day',4)
add(17,'Argos Recognizes His Master','The neglected old dog recognizes Odysseus at once and dies after seeing him home.','palace-yard',['odysseus','eumaeus','argos'],[], 'The next day',3)
add(17,'Antinous Strikes the Beggar','Odysseus begs from each suitor; Antinous throws a stool and intensifies the coming judgment.','palace-hall',['odysseus','antinous','telemachus','penelope'],[], 'Minutes later',4)
add(18,'The Beggar Defeats Irus','Forced into a public fight, Odysseus drops the palace beggar with one controlled blow.','palace-yard',['odysseus','antinous','telemachus','amphinomus'],[], 'That afternoon',3)
add(18,'Penelope Receives the Suitors’ Gifts','Athena enhances Penelope’s presence; she rebukes the suitors and makes them replenish the household.','palace-hall',['penelope','athena','antinous','eurymachus','odysseus'],['shroud'], 'That evening',3)
add(19,'The Weapons Are Removed','Odysseus and Telemachus carry helmets, shields, and spears out of the hall under Athena’s light.','storeroom',['odysseus','telemachus','athena'],[], 'That night',3)
add(19,'Penelope Questions the Stranger','The disguised Odysseus describes clothing and a brooch accurately enough to make Penelope hope.','palace-hall',['odysseus','penelope'],['brooch'], 'Later that night',3)
add(19,'Eurycleia Finds the Scar','While washing the stranger’s feet, Eurycleia recognizes the boar-hunt scar and is sworn to silence.','palace-hall',['odysseus','eurycleia','penelope'],['scar'], 'Moments later',4)
add(20,'The Last Morning of Restraint','Melanthius and Melantho abuse the disguised king while Zeus’s thunder favours the household.','palace-hall',['odysseus','telemachus','melanthius','melantho','zeus'],[], 'The next morning',4)
add(20,'Theoclymenus Sees the Hall in Blood','The seer answers the suitors’ laughter with a vision of darkness, blood, and shades descending to Hades.','palace-hall',['theoclymenus','telemachus','antinous','eurymachus'],[], 'Near noon',4)
add(21,'Penelope Announces the Contest','Penelope brings out the bow and declares she will marry whoever strings it and shoots through the axes.','palace-hall',['penelope','eurycleia','antinous','eurymachus','telemachus','odysseus'],['bow','axes'], 'That afternoon',4)
add(21,'The Bow Sings','After every suitor fails, Odysseus strings the bow smoothly and sends an arrow through all twelve axes.','palace-hall',['odysseus','telemachus','antinous','eurymachus'],['bow','axes'], 'Minutes later',5)
add(22,'Antinous Falls','The first revealed arrow kills Antinous at his cup; Odysseus names the suitors’ crimes.','palace-hall',['odysseus','antinous','eurymachus','telemachus'],['bow'], 'Immediately',5)
add(22,'The Hall Is Reclaimed','Odysseus, Telemachus, Eumaeus, and Philoetius defeat the armed suitors while Melanthius secretly arms them.','palace-hall',['odysseus','telemachus','eumaeus','philoetius','eurymachus','melanthius','amphinomus','athena'],['bow'], 'One battle',5)
add(22,'Phemius and Medon Are Spared','Phemius claims he sang under coercion, and Medon emerges from hiding under Telemachus’s protection.','palace-hall',['odysseus','telemachus','phemius','medon'],[], 'After the battle',2)
add(23,'Penelope Tests the Stranger','Penelope orders the marriage bed moved; Odysseus’s outraged description reveals the secret only they share.','olive-bed',['odysseus','penelope','eurycleia'],['olive-bed'], 'Later that night',4)
add(23,'The Marriage Is Restored','Athena lengthens the night while husband and wife exchange the histories of their separation.','olive-bed',['odysseus','penelope','athena'],['olive-bed'], 'One extended night',2)
add(24,'The Suitors Reach Hades','Hermes guides the suitors’ shades past Ocean while Agamemnon praises Penelope’s fidelity.','hades-house',['hermes','antinous','eurymachus'],[], 'Meanwhile',3)
add(24,'Laertes Recognizes His Son','Odysseus tests Laertes, then proves himself through the scar and shared knowledge of the orchard.','laertes-farm',['odysseus','laertes','telemachus'],['scar'], 'The next day',3)
add(24,'Athena Imposes Peace','Laertes kills the leading attacker, but Zeus and Athena halt the feud and bind Ithaca to peace.','assembly',['odysseus','laertes','telemachus','athena','zeus'],[], 'That afternoon',4)

// Snapshot text describes each participant's immediate condition or action.
// Arrays intentionally follow the character order on the matching event.
const eventStates={
 'The Gods Debate Odysseus':['Arguing that the long-delayed return should resume.','Authorizing Athena and Hermes to set the return in motion.','Absent from council and still obstructing the voyage.'],
 'Mentes Visits Ithaca':['Testing Telemachus while concealed in the form of Mentes.','Newly resolved to seek news and challenge the suitors.','Upstairs, grieving without yet knowing the visitor’s identity.','Feasting in the palace and dismissive of the young heir.'],
 'Penelope Challenges the Song':['Overcome by the song of failed returns and asking for silence.','Asserting authority over the hall despite his mother’s grief.','Watching the household’s division while continuing the feast.','Performing for the suitors until Penelope interrupts him.'],
 'The Ithacan Assembly':['Speaking publicly against the suitors for the first time.','Rejecting blame and defying the heir before the island.','Guarding the secret preparations for Telemachus’s departure.'],
 'A Ship Leaves by Night':['Leaving Ithaca secretly with a newly gathered crew.','Guiding the expedition and supplying practical help in disguise.','Keeping the voyage secret from Penelope after provisioning it.'],
 'Sacrifice at Pylos':['Anxious but entering Nestor’s public household as a guest.','Encouraging Telemachus, then revealing divinity through departure.','Welcoming the unknown prince amid the coastal sacrifice.','Receiving Telemachus as a young companion in his father’s house.','Honoured by the Pylian sacrifice though hostile elsewhere to Odysseus.'],
 'Nestor’s Counsel':['Listening for news and learning from an ordered royal household.','Recounting the divided returns and directing the search to Sparta.'],
 'The Court at Sparta':['Received as Odysseus’s son and moved by the hosts’ memories.','Recognizing the guest’s lineage and offering royal hospitality.','Recognizing Odysseus in Telemachus’s appearance and recalling Troy.'],
 'The Sign of Proteus':['Learning at last that his father is alive on Ogygia.','Retelling the hard-won prophecy he obtained in Egypt.','Hearing confirmation that the long absence is not death.','Present through Menelaus’s account as the source of the revelation.'],
 'The Suitors Plan an Ambush':['Organizing a murder at sea before the heir can return.','Supporting the plot while maintaining a smoother public manner.','Newly informed of her son’s voyage and terrified for him.'],
 'Hermes Reaches Ogygia':['Delivering Zeus’s unambiguous order that the captive be released.','Angry and wounded, but compelled to help Odysseus depart.','Still longing for Ithaca and unaware that release has been ordered.','Exercising distant authority through his messenger.'],
 'The Raft Departs':['Choosing mortal homecoming over Calypso’s offer of immortality.','Supplying tools and provisions while reluctantly letting him go.'],
 'Poseidon’s Storm':['Exhausted, shipwrecked, and trusting Ino’s veil for survival.','Returning from Ethiopia and destroying the raft in anger.','Restraining the winds so the swimmer can reach land.','Appearing from the sea to lend her life-preserving veil.'],
 'Nausicaa’s Dream':['Planting a dream that sends the princess to the shore.','Awakened with marriage in mind and arranging the washing expedition.'],
 'The Stranger on the Shore':['Naked, salt-crusted, and carefully appealing from a distance.','Holding her ground, clothing the stranger, and explaining the city.'],
 'Athena’s Grove':['Waiting outside the city to protect Nausicaa’s reputation.','Returning separately and instructing the stranger where to go.','Preparing concealment and guidance for the palace approach.'],
 'Odysseus Supplicates Arete':['At the hearth, physically spent and pleading for passage home.','Judging the stranger by his conduct and her recognizable weaving.','Granting protection and promising eventual transport.','Concealing her favourite in mist until the decisive appeal.'],
 'The Phaeacian Games':['Stung by insult and publicly proving undiminished strength.','Trying to honour the guest and repair a breach of hospitality.','Watching the stranger who will soon depart her world.'],
 'Demodocus Sings of Troy':['Unable to hide his grief when his own Trojan stratagem is sung.','Stopping the performance and demanding the weeping guest’s identity.','Observing the stranger whose clothing she already recognizes.','Singing of the wooden horse without knowing the hero sits nearby.'],
 'The Raid on Ismarus':['Unable to force a prompt retreat after the initial victory.','Remaining with the men whose delay brings the Cicones’ counterattack.'],
 'The Lotus-Eaters':['Dragging drugged scouts back and physically securing the crew.','Witnessing the lotus erase his companions’ desire for home.'],
 'Trapped in the Cyclops’s Cave':['Watching men die while calculating a possible escape.','Sealing the captives inside and rejecting the protection of Zeus.','Invoked as guardian of guests, but openly scorned by Polyphemus.'],
 'Nobody Blinds Polyphemus':['Executing the false-name plan and driving the heated stake.','Drunk, blinded, and deceived into defeating his own call for help.'],
 'The Name Shouted from the Sea':['Safe offshore but surrendering anonymity to wounded pride.','Learning his attacker’s identity and praying for a ruined return.','Receiving his son’s appeal to punish the named offender.'],
 'Aeolus Bags the Winds':['Trusted with the sealed bag and a clear westward passage.','Hosting the traveller and binding every adverse wind.','Sailing with the crew while the captain guards the mysterious gift.'],
 'Ithaca Lost in Sight':['Waking to find home replaced by a released tempest.','Opening the bag with the crew under the suspicion of hidden treasure.','Refusing further aid when the storm drives the ship back.'],
 'Aeolus Refuses a Second Passage':['Begging for another chance after the crew’s mistrust destroys the first.','Driving the returned fleet away as people visibly hated by the gods.','Facing the open sea again without divine wind or a safe course.'],
 'The Laestrygonian Harbour':['Keeping his own ship outside the fatal narrow anchorage.','Escaping aboard the sole vessel beyond reach of the cliff attack.','Directing the giant assault that annihilates eleven ships.'],
 'Circe Transforms the Scouts':['Enchanting the scouting party and penning the transformed men.','Escaping the drugged feast and running back with the warning.','Arming himself to recover the missing companions.'],
 'Moly Defeats the Spell':['Protected by moly and forcing Circe to swear a binding oath.','Defeated by resistance to her drug and restoring the transformed crew.','Supplying the protective herb and precise instructions.','Watching his warning give way to an unexpected alliance.'],
 'A Year with Circe':['Comfortable but recalled to purpose by his impatient companions.','Hosting Odysseus as lover and preparing to guide his departure.','Pressing the captain to end the long, dangerous delay.'],
 'The Black Ship Reaches the Cimmerians':['Following Circe’s directions into a shore without ordinary sunlight.','Helping beach the ship and carry the offerings toward the boundary of the dead.'],
 'Elpenor Asks for Burial':['Holding the shades back until the neglected dead man speaks.','Unburied and pleading for rites, an oar, and a marked grave.'],
 'Tiresias Defines the Return':['Receiving the conditions of survival and the prophecy beyond homecoming.','Drinking the blood and speaking with undiminished prophetic authority.'],
 'Anticleia Embraces Only Air':['Learning that grief for him contributed to his mother’s death.','Speaking tenderly but unable to take bodily form in her son’s arms.'],
 'The Heroes Among the Dead':['Questioning the famous dead and revising the meaning of heroic glory.','Warning from his own murdered homecoming against careless trust.','Ruling the shades yet declaring life preferable to honour among the dead.'],
 'The Sirens’ Song':['Bound to the mast, desperate to be released toward the song.','Sailing deafened by wax and tightening the ropes at his captain’s signals.'],
 'Scylla Takes Six':['Armed but helpless as six sailors are lifted from the deck.','Driving the ship onward through the crew’s most immediate horror.','Feeding from the passing vessel with all six heads.'],
 'The Cattle Are Slaughtered':['Asleep apart after praying for escape from the island.','Persuading the starving crew that sacrifice is preferable to hunger.','Outraged by the killing of his consecrated herd.','Promising punishment after Helios threatens to withdraw his light.'],
 'Helios Demands Justice':['Demanding reparation for the slaughter and threatening to shine among the dead.','Promising to strike the guilty ship with a thunderbolt.'],
 'Zeus Destroys the Last Ship':['The only survivor, clinging to wreckage without crew or vessel.','Sending the thunderbolt that enforces judgment for sacrilege.','No longer the immediate attacker, but still barring an easy return.'],
 'The Sleeping King Lands':['Asleep on Ithacan soil beside the accumulated gifts.','Completing his promise through a swift, secret night voyage.'],
 'Athena Reveals Ithaca':['Disoriented, then overjoyed and immediately planning concealment.','Revealing the island, hiding the treasure, and imposing the beggar shape.'],
 'Eumaeus Welcomes the Beggar':['Testing the household while accepting shelter under a false identity.','Protecting an unknown guest and lamenting his absent master.'],
 'A Cretan Tale':['Improvising a layered Cretan history to test the swineherd.','Listening with sympathy yet refusing to believe Odysseus is near.'],
 'Telemachus Leaves Sparta':['Accepting parting gifts while urgently turning toward Ithaca.','Prompting the departure and prescribing the safer route home.','Giving final counsel and a crafted mixing bowl.','Interpreting the eagle omen as favouring Odysseus’s line.','Escorting his friend from Sparta before returning to Pylos.'],
 'The Ambush Is Avoided':['Following Athena’s instructions and landing beyond the killers’ watch.','Guiding the ship around the strait and toward a concealed arrival.','Waiting at sea while his intended victim passes safely elsewhere.'],
 'Athena Restores Odysseus':['Briefly restored to royal form and exposing his identity to his son.','Moving from disbelief to tears in his father’s arms.','Transforming the beggar and directing the reunion.','Sent away from his hut so the recognition remains private.'],
 'Father and Son Plan':['Counting the suitors and designing a strategy built on secrecy.','Accepting the dangerous task of removing the hall’s weapons.'],
 'Argos Recognizes His Master':['Forced to conceal emotion as his abandoned hound recognizes him.','Leading the guest past the neglected dog without knowing the truth.','Recognizing his master at once and dying after twenty years of waiting.'],
 'Antinous Strikes the Beggar':['Absorbing the blow without surrendering his disguise.','Escalating contempt into physical violence against a guest.','Watching his father’s humiliation while preserving the plan.','Hearing of the outrage and wishing the attacker’s death.'],
 'The Beggar Defeats Irus':['Revealing controlled strength without fully exposing himself.','Sponsoring the cruel entertainment and reassessing the beggar.','Trying to limit escalation while observing the easy victory.','Offering the victor food and receiving a grave warning to leave.'],
 'Penelope Receives the Suitors’ Gifts':['Commanding the room and turning courtship back into material obligation.','Enhancing Penelope’s presence to sharpen the contest around her.','Contributing gifts while continuing to occupy the household.','Using polished speech and a costly necklace to retain favour.','Watching his wife’s strategy from within the beggar disguise.'],
 'The Weapons Are Removed':['Clearing the hall while maintaining the fiction of smoke protection.','Carrying armour in silence and committing fully to the coming fight.','Providing supernatural light that Eurycleia cannot see.'],
 'Penelope Questions the Stranger':['Sustaining the Cretan disguise while supplying exact private memories.','Grieving as the stranger’s description makes hope dangerous again.'],
 'Eurycleia Finds the Scar':['Seizing the nurse’s throat gently enough to preserve silence.','Recognizing her master by touch and struggling to contain joy.','Nearby but prevented by Athena from noticing the recognition.'],
 'The Last Morning of Restraint':['Containing rage through the final round of household abuse.','Watching the servants’ conduct and awaiting the agreed signal.','Mocking and kicking the beggar while serving the suitors.','Taunting the stranger and rejecting his warning.','Answering Odysseus’s prayer with thunder from a clear sky.'],
 'Theoclymenus Sees the Hall in Blood':['Seeing darkness, blood, and crowded shades where the suitors see a feast.','Hearing the prophecy while keeping his father’s plan concealed.','Laughing at the seer and remaining inside the doomed hall.','Joining the mockery and dismissing the warning.'],
 'Penelope Announces the Contest':['Placing the bow before the suitors as a decisive test.','Bringing the bow from storage while still guarding Odysseus’s secret.','Confident that possession can be converted into legitimate marriage.','Competing for Penelope while failing to master the weapon.','Attempting the bow, then yielding the contest on his father’s signal.','Waiting in disguise for lawful access to his own weapon.'],
 'The Bow Sings':['Stringing the bow effortlessly and completing the impossible shot.','Closing the doors and reading the shot as the final signal.','Realizing the beggar possesses the mastery every suitor lacks.','Watching confidence collapse into immediate danger.'],
 'Antinous Falls':['Opening the reckoning with a precise arrow and public accusation.','Killed without warning while drinking from the household’s cup.','Offering restitution only after the dominant suitor is dead.','Taking his place beside his revealed father with weapons ready.'],
 'The Hall Is Reclaimed':['Fighting openly as king with bow, spear, and Athena’s support.','Holding the line beside his father despite a momentary mistake.','Locking exits and carrying weapons for the returning master.','Securing the doors and fighting beside the household.','Killed after failed negotiation and armed resistance.','Stealing weapons from the storeroom until the loyal servants catch him.','Killed in the battle despite the warning previously offered to him.','Deflecting enemy spears and revealing the certainty of divine judgment.'],
 'Phemius and Medon Are Spared':['Judging their claims and accepting Telemachus’s testimony.','Interceding for two servants who did not willingly join the suitors.','Clinging to the altar and explaining that he performed under coercion.','Emerging from concealment and confirming his loyalty to the household.'],
 'Penelope Tests the Stranger':['Reacting to the order to move the bed with knowledge only its builder possesses.','Withholding recognition until the rooted bed elicits the decisive truth.','Watching the final test after carrying the news upstairs.'],
 'The Marriage Is Restored':['Reunited with his wife and recounting the years of wandering.','Finally accepting the returned man as her husband.','Lengthening the night so recognition and narrative can unfold.'],
 'The Suitors Reach Hades':['Conducting the newly dead shades to the underworld.','A shade among the company whose violence has ended.','A shade forced to hear Agamemnon praise Penelope’s fidelity.'],
 'Laertes Recognizes His Son':['Dropping the final disguise after testing his father’s endurance.','Revived by the scar and the exact memory of orchard trees.','Witnessing the reunion of the two older generations.'],
 'Athena Imposes Peace':['Prepared to continue fighting until the divine command stops him.','Restored to martial confidence and striking the attackers’ leader.','Standing with father and grandfather at the edge of renewed feud.','Calling a halt and binding both sides to forget the bloodshed.','Confirming Athena’s settlement with thunder and sovereign authority.'],
}
// Keep snapshots strictly physical: figures who are invoked, remembered, reported,
// or acting from another place belong in mentionedCharacterIds, not at the marker.
const absentMentions={
 'The Gods Debate Odysseus':['poseidon'],
 'Mentes Visits Ithaca':['penelope'],
 'The Ithacan Assembly':['eurycleia'],
 'Sacrifice at Pylos':['poseidon'],
 'The Sign of Proteus':['proteus'],
 'The Suitors Plan an Ambush':['penelope'],
 'Hermes Reaches Ogygia':['odysseus','zeus'],
 'Poseidon’s Storm':['athena'],
 'The Phaeacian Games':['nausicaa'],
 'Trapped in the Cyclops’s Cave':['zeus'],
 'The Name Shouted from the Sea':['poseidon'],
 'Ithaca Lost in Sight':['aeolus'],
 'Moly Defeats the Spell':['eurylochus'],
 'The Cattle Are Slaughtered':['helios','zeus'],
 'Zeus Destroys the Last Ship':['zeus','poseidon'],
 'The Sleeping King Lands':['alcinous'],
 'The Ambush Is Avoided':['athena','antinous'],
 'The Last Morning of Restraint':['zeus'],
 'Athena Imposes Peace':['zeus'],
}
for(const e of E){
 const rawStates=eventStates[e.title]
 if(!rawStates||rawStates.length!==e.chars.length)throw Error(`Missing per-character states: ${e.title}`)
 const mentioned=new Set(absentMentions[e.title]??[])
 e.mentions=e.chars.filter(c=>mentioned.has(c))
 e.states=rawStates.filter((_,i)=>!mentioned.has(e.chars[i]))
 e.chars=e.chars.filter(c=>!mentioned.has(c))
}

